func TestUpdaterUpdateProjectFile(t *testing.T) {
	t.Parallel()

	dir, err := os.MkdirTemp("", "updater-nuget-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := os.RemoveAll(dir); err != nil {
			t.Errorf("remove temporary directory: %v", err)
		}
	})

	file := filepath.Join(dir, "demo.csproj")
	if err := os.WriteFile(file, []byte("<Project>\n  <Version>1.2.3</Version>\n</Project>\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	if err := NewUpdater().Update(file, "1.3.0"); err != nil {
		t.Fatalf("Update() error = %v", err)
	}

	got, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(got), "<Version>1.3.0</Version>") {
		t.Fatalf("updated file = %s", got)
	}
}

func TestUpdaterDiff(t *testing.T) {
	t.Parallel()

	file := filepath.Join(t.TempDir(), "demo.csproj")
	original := "<Project>\n  <Version>1.2.3</Version>\n</Project>\n"
	if err := os.WriteFile(file, []byte(original), 0o644); err != nil {
		t.Fatal(err)
	}

	diff, err := NewUpdater().Diff(file, "1.3.0")
	if err != nil {
		t.Fatalf("Diff() error = %v", err)
	}
	if !strings.Contains(diff, "--- a/"+file+"\n+++ b/"+file+"\n") {
		t.Fatalf("diff = %s", diff)
	}
	if !strings.Contains(diff, "-  <Version>1.2.3</Version>\n+  <Version>1.3.0</Version>\n") {
		t.Fatalf("diff = %s", diff)
	}
	got, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != original {
		t.Fatalf("Diff() modified file: %s", got)
	}
}

